export function getUnionsByUpazila(district: string, upazila: string): string[] {
  const cleanDistrict = district.trim();
  const cleanUpazila = upazila.trim();
  if (!cleanUpazila) return [];
  return unionsByDistrictUpazila[`${cleanDistrict}::${cleanUpazila}`] ?? unionsByUpazila[cleanUpazila] ?? [];
}

export const wards = ["১", "২", "৩", "৪", "৫", "৬", "৭", "৮", "৯", "১০", "১১", "১২", "১৩", "১৪", "১৫", "১৬", "১৭", "১৮", "১৯", "২০"];

export function formatBdAddress(p: {
  division?: string; district?: string; upazila?: string;
  union?: string; ward?: string; village?: string;
}): string {
  return [p.village, p.union, p.ward ? `ওয়ার্ড ${p.ward}` : "", p.upazila, p.district, p.division]
    .filter((x) => x && x.trim()).join(", ");
}
